class Client:
 def __init__(self,staff=False):self.cookie='';self.csrf='';self.staff=staff
 def call(self,route,data=None,expected=200):
  req=urllib.request.Request(origin+('/api/read2lead/gifts-staff/' if self.staff else '/api/read2lead/self-learn/')+route,data=None if data is None else json.dumps(data,ensure_ascii=False).encode(),headers={'Origin':origin,'Content-Type':'application/json',**({'Cookie':self.cookie} if self.cookie else {}),**({('X-R2L-Gift-CSRF' if self.staff else 'X-R2L-CSRF'):self.csrf} if self.csrf else {})})
  try:r=urllib.request.urlopen(req,timeout=15)
  except urllib.error.HTTPError as error:r=error
  with r:
   value=json.load(r);assert r.status==expected,(route,r.status,value)
   if r.headers.get('Set-Cookie'):self.cookie=r.headers['Set-Cookie'].split(';')[0]
   if value.get('csrf'):self.csrf=value['csrf']
   return value
